"""Static, readable shell for a replay of measured Ethernet capture records."""
import html
import json
from agent_replay import render as render_agent_replay
from observatory import render as render_observatory


def render(root, layout, heading):
    manifest = json.loads((root/'data/downloads/manifest.json').read_text())
    downloads = '<section class="prose" id="downloads"><h2>Скачать и проверить</h2><p>Доступно без регистрации. Архивы — снимки опубликованных материалов; контрольные суммы позволяют проверить загрузку.</p><div class="download-records">'
    for bundle in manifest['bundles']:
        downloads += f'''<div><h3><a href="data/downloads/{bundle['name']}?v={bundle['sha256'][:12]}" download>{html.escape(bundle['label'])} ↓</a></h3><p>{html.escape(bundle['scope'])}</p><p class="small">{bundle['bytes']/1024:.1f} КиБ · {bundle['files']} файлов</p><details><summary>SHA-256 архива</summary><code>{bundle['sha256']}</code></details></div>'''
    downloads += '</div><p><a href="data/downloads/SHA256SUMS.txt">Все контрольные суммы</a> · <a href="data/downloads/manifest.json">Состав снимков</a> · <a href="history.html">Читать историю на сайте</a></p></section>'
    (root/'downloads.html').write_text(layout('experiments.html', 'Материалы для скачивания', heading('Материалы проекта', 'Исходный код, инструкции, измерения и история решений в двух открытых архивах.')+downloads))

    body = heading('Обмен по кадрам', 'Исследуйте сохранённые задачи агентов и отдельный покадровый опыт SHA-256; условия и ограничения каждого запуска указаны рядом.')
    body += render_observatory(root)
    body += '''<section class="section replay" aria-labelledby="replay-heading"><div class="replay-top"><div><h2 id="replay-heading">Три ОС без TCP/IP</h2><p class="small">Сохранённый опыт · 27 октября 2026 · один физический CI-хост</p></div><label for="replay-scenario">Сценарий<select id="replay-scenario" disabled><option value="baseline">Посредник работает · 16 / 16</option><option value="relay-down">Посредник остановлен · 0 / 16</option></select></label></div>
<p class="note">Запись настоящего опыта SHA-256: три гостя на одном CI-хосте, без LLM. Новый опыт на разных физических машинах ещё не подтверждён.</p>
<div class="replay-map" aria-label="Физические каналы A — R — B; прямого канала A — B нет"><div class="replay-node" data-node="A"><strong>A</strong><span>Отправитель</span><small>Linux · INET отсутствует</small></div><div class="replay-link" aria-hidden="true"><span>Ethernet</span><i></i></div><div class="replay-node" data-node="R"><strong>R</strong><span>Посредник</span><small>Два порта</small></div><div class="replay-link" aria-hidden="true"><span>Ethernet</span><i></i></div><div class="replay-node" data-node="B"><strong>B</strong><span>Исполнитель</span><small>SHA-256 локально</small></div><span id="replay-packet" hidden aria-hidden="true"></span></div>
<div class="replay-counts"><p><strong id="replay-total">90</strong> кадров в полном захвате</p><p><strong id="replay-completed">16 / 16</strong> задач завершено — итог опыта</p><p><strong>12</strong> отказов IP-сокетов на трёх ОС</p></div>
<div class="replay-controls" role="group" aria-label="Управление воспроизведением"><button class="button" type="button" id="replay-play" disabled>Воспроизвести</button><button class="button secondary" type="button" id="replay-back" disabled>Назад</button><button class="button secondary" type="button" id="replay-next" disabled>Следующий кадр</button><label for="replay-speed">Скорость<select id="replay-speed"><option value="650">Наглядно · 650 мс / кадр</option><option value="150">Быстро · 150 мс / кадр</option><option value="1200">Медленно · 1,2 с / кадр</option></select></label></div>
<label class="replay-scrub-label" for="replay-position">Кадр <output id="replay-position-label">1 из 90</output></label><input id="replay-position" type="range" min="0" max="89" value="0" disabled><p class="small">Интервал показа условный; часы каждого PCAP считаются отдельно. Шаги работают без движения. <a href="#replay-clock">Как читать время</a></p><p id="replay-status" role="status" aria-live="polite">Загружаем проверенный захват…</p><button class="button secondary" id="replay-retry" type="button" hidden>Загрузить запись ещё раз</button>
<div class="replay-inspect"><section aria-labelledby="replay-frame-heading"><h3 id="replay-frame-heading">Что передано</h3><p id="replay-frame-line">Все кадры доступны в исходных файлах ниже.</p><dl id="replay-fields"></dl><div id="replay-byte-layout" aria-label="Состав кадра"></div><details><summary>Содержимое и проверка кадра</summary><p id="replay-payload-note"></p><pre><code id="replay-payload"></code></pre><p class="small">SHA-256 полного кадра</p><code id="replay-frame-hash"></code><p><a id="replay-pcap" href="data/strict-native-2026-10-27/baseline/ar.pcap" download>Исходный PCAP</a></p><details><summary>Полный кадр в HEX</summary><pre><code id="replay-frame-hex"></code></pre></details></details></section><section aria-labelledby="replay-events-heading"><h3 id="replay-events-heading">Журнал кадров</h3><p class="small">Все кадры обоих каналов. Порядок внутри канала точный; между каналами сопоставлены задачи и ответы. Для повторов HELLO общий порядок неизвестен. Выберите строку, чтобы изучить её.</p><ol id="replay-events" aria-label="Все кадры захвата"></ol></section></div></section>
<section class="prose"><h2>Что произошло при остановке R</h2><p>В отрицательном прогоне R остановлен после готовности сетевых интерфейсов. В захвате остались HELLO и попытки доставки; ни одна задача не завершилась. Запасного канала в этой топологии нет, поэтому маршрут не восстановился.</p><p>Точное время остановки R не записано в PCAP отдельным событием. Проигрыватель его не придумывает: доступны кадры и тайм-аут A в консольном журнале.</p><p><a id="replay-receipt" href="data/strict-native-2026-10-27/baseline/receipt.json">Квитанция выбранного сценария</a> · <a href="data/strict-native-2026-10-27/relay-down/A.console.log">Тайм-аут в ОС A</a></p></section>
<section class="prose" id="replay-clock"><h2>Время и границы доказательства</h2><p>Часы двух PCAP относятся к разным гостям: вычитать их для оценки перехода нельзя. Порядок сохраняет очередь каждого канала и совпадение задач / результатов на двух портах R. Общий порядок повторов HELLO не установлен. Движение точки не измеряет задержку канала.</p><p>Каждый кадр проверен экспортёром: границы, CRC, Ed25519, соответствие ID открытому ключу, адресат и полезная нагрузка. Браузер показывает сохранённый результат этой проверки. Шифрования нет; ключи хранятся в памяти, доверие при первом контакте, пересылка задана таблицей.</p><p>Нативная доставка пяти обычных ВМ с LLM — другой, более ранний опыт: там IP остаётся в ОС для управления. Эти результаты не объединяются в доказательство работы LLM внутри строгой ОС.</p><p><a href="saved-trace.html">Фактическое сообщение между моделями</a> · <a href="experiments.html#llm">Измеренное сравнение с IP</a> · <a href="rfc-0006.html#strict-measured">Полный отчёт строгого опыта</a> · <a href="https://github.com/relcom-technologies/ipvx-research/actions/runs/40500966557">Настоящий запуск</a></p><noscript><p>Для пошагового проигрывателя нужен JavaScript. Сводки, исходный код, захваты и квитанции доступны по ссылкам без JavaScript.</p></noscript></section>'''
    agents = render_agent_replay(root)
    if agents:
        body = body.replace('Новый опыт на разных физических машинах ещё не подтверждён.', 'Отдельный подтверждённый проход с моделями на разных физических хостах показан ниже.')
        body = body.replace('<section class="section replay"', '<p class="prose"><a class="button secondary" href="#native-agents">К обмену моделей на трёх хостах ↓</a></p><section class="section replay"', 1)
    body += agents
    body += downloads
    page = layout('experiments.html', 'Обмен по кадрам', body).replace('<body>', '<body class="replay-page">')
    page = page.replace('</head>', '<link rel="stylesheet" href="assets/replay.css"><script src="assets/replay.js" defer></script><link rel="stylesheet" href="assets/agent-replay.css"><script src="assets/agent-replay.js" defer></script><link rel="stylesheet" href="assets/observatory.css"><script src="assets/observatory.js" defer></script></head>')
    (root/'packet-replay.html').write_text(page)
